WITH valid AS (SELECT id, device_code, reading_ts, humidity, pressure, firmware, CAST(humidity AS INT) AS humidity_int, HOUR(reading_ts) AS reading_ts_hour FROM device_readings WHERE reading_ts > TIMESTAMP '2025-09-01 02:00:00' AND device_code NOT IN ('DV-04', 'DV-02', 'DV-01')), remaining_keys AS (SELECT firmware FROM valid EXCEPT DISTINCT SELECT firmware FROM device_readings WHERE device_code = 'DV-02'), kept_rows AS (SELECT s.* FROM valid s JOIN remaining_keys k ON s.firmware = k.firmware), with_windows AS (SELECT device_code, humidity, pressure, firmware, reading_ts_hour, CORR(pressure, humidity) OVER (PARTITION BY device_code) AS corr_pressure_humidity FROM kept_rows), valid_device_readings AS (SELECT *, CONCAT(firmware, ' - ', device_code) AS firmware_device_code FROM with_windows WHERE humidity BETWEEN 51 AND 63), scored AS (SELECT firmware, reading_ts_hour, corr_pressure_humidity, AVG(reading_ts_hour) OVER (PARTITION BY device_code) AS device_code_avg_reading_ts_hour, CORR(humidity, pressure) OVER (PARTITION BY device_code) AS corr_humidity_pressure FROM valid_device_readings) SELECT firmware, reading_ts_hour FROM scored;
